import React from "react";
import { Link } from "react-router-dom";
import { useCart } from "../contexts/CartContext";

export default function Navbar() {
  const { cart } = useCart();

  return (
    <div
      style={{
        padding: "12px 20px",
        borderBottom: "1px solid #e5e5e5",
        background: "#fafafa",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
      }}
    >
      <h2 style={{ margin: 0, fontSize: "22px", fontWeight: "600" }}>
        E-Commerce App
      </h2>

      <div style={{ display: "flex", gap: "14px", fontSize: "16px" }}>
        <Link style={navLink} to="/">Products</Link>
        <Link style={navLink} to="/cart">Cart ({cart.length})</Link>
        <Link style={navLink} to="/login">Login</Link>
        <Link style={navLink} to="/register">Register</Link>
      </div>
    </div>
  );
}

const navLink = {
  textDecoration: "none",
  color: "#007bff",
  fontWeight: "500",
};
